```sql
SELECT COUNT(*) FROM connected c JOIN atom a ON c.atom_id = a.atom_id WHERE a.atom_id LIKE 'TR%_19';
```

```sql
SELECT CAST(SUM(CASE WHEN element = 'h' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) as percent;
FROM atom a, molecule m
WHERE a.molecule_id = 'TR206';
```

```sql
SELECT publisher_id FROM publisher WHERE publisher_name = 'Star Trek';
```

```sql
SELECT m.major_name FROM member m JOIN major m2 ON m.link_to_major = m2.major_id;
```

```sql
SELECT SUM(s.paid) as total_amount_spent FROM expense s JOIN budget b ON s.link_to_budget = b.budget_id WHERE s.category = 'Food';
```

```sql
SELECT CAST(SUM(weight_kg) AS INTEGER) - CAST(SUM(weight_kg) AS INTEGER) FROM superpower WHERE full_name = 'Emil Blonsky';
```

```sql
SELECT CAST(VOTE_COUNT AS INTEGER) * 1.0 / VOTE_TOTAL FROM votes;
```

```sql
SELECT id FROM cards WHERE duelDeck = 'a';
```

```sql
SELECT CAST(ROUND(SUM(CASE WHEN borderColor = 'borderless' THEN 1 ELSE 0 END) / COUNT(*) * 100, 2) AS REAL) as percentage FROM cards;
```
